<?php require __DIR__.'/../app/bootstrap.php';require_login();require_permission('logistics.request');verify_csrf();$no=generate_number($pdo,'SPR','logistics_orders','request_no');$approval=($_POST['submit_approval']??'1')==='1'?'Menunggu Approval':'Draft';$stmt=$pdo->prepare('INSERT INTO logistics_orders(request_no,unit_id,item_name,quantity,vendor,order_date,expected_date,status,approval_status,requested_by,total_cost) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$no,($_POST['unit_id']??'')?:null,trim($_POST['item_name']),(int)$_POST['quantity'],trim($_POST['vendor']??''),$_POST['order_date'],($_POST['expected_date']??'')?:null,'Dipesan',$approval,current_user()['id'],(float)($_POST['total_cost']??0)]);$id=(int)$pdo->lastInsertId();audit($pdo,'CREATE','logistics_order',$id,'Permintaan '.$no);add_history($pdo,'logistics_order',$id,null,$approval,'Permintaan spare part dibuat');if($approval==='Menunggu Approval')notify($pdo,null,'approval','Approval spare part diperlukan',$no.' - '.trim($_POST['item_name']),page_url('approvals'));flash('success','Permintaan '.$no.' disimpan.');redirect('../'.page_url('logistics'));
